//! Quality snapshot for double, generated by sdsp-test-kit.
//!
//! Fixed probes through the real CLAP plugin, recorded to `tests/quality.snap`.
//! A change in any of these numbers is a change in how the plugin sounds, and
//! the test fails until the snapshot is re-recorded on purpose:
//!
//!     SDSP_UPDATE_SNAPSHOTS=1 cargo test -p superduper-double --test quality

use clack_common::events::{event_types::ParamValueEvent, Pckn};
use clack_common::utils::{ClapId, Cookie};
use sdsp_test_kit::probes::{self, db};
use sdsp_test_kit::{render_effect, PluginUnderTest, Suite};
use superduper_double as dbl;

struct Target;
impl PluginUnderTest for Target {
    type Plugin = dbl::SuperDuperDouble;
    const ID: &'static std::ffi::CStr = c"co.superduperai.double";
}

const SR: f64 = 48_000.0;

/// Render with some params set at the first block.
fn render_set(x: &[f32], set: &'static [(usize, f64)]) -> (Vec<f32>, Vec<f32>) {
    sdsp_test_kit::host::render_with::<Target>(SR, 512, x, x, move |pos, buf| {
        if pos == 0 {
            for &(i, v) in set {
                let id = ClapId::new(i as u32);
                buf.push(&ParamValueEvent::new(0, id, Pckn::match_all(), v, Cookie::empty()));
            }
        }
    })
}

#[test]
fn quality_snapshot() {
    // The drift is seeded and restarts identically, so the default 1 dB
    // tolerance is not hiding a random source.
    let mut s = Suite::new("double", concat!(env!("CARGO_MANIFEST_DIR"), "/tests/quality.snap"))
        .default_tolerance(1.0);
    let frames = 1 << 15;

    let tone = probes::tone(SR as f32, 1000.0, 0.5, frames);
    let (out, _) = render_effect::<Target>(SR, &tone, &tone);
    s.record("tone_gain_db", probes::gain_db(&tone, &out));
    s.record("tone_peak_db", db(probes::peak(&out)));
    for (band, level) in probes::band_shape(&out, SR as f32) {
        s.record(format!("tone_band_{band}"), level);
    }

    let voice = sdsp_test_kit::signals::voiced(frames as f32 / SR as f32);
    let (vout, vr) = render_effect::<Target>(SR, &voice, &voice);
    s.record("voice_gain_db", probes::gain_db(&voice, &vout));
    s.record("voice_max_step", probes::max_step(&vout));
    s.record("voice_lr_diff_db", probes::gain_db(&vout, &vout.iter().zip(&vr).map(|(a, b)| a - b).collect::<Vec<_>>()));
    for (band, level) in probes::band_shape(&vout, SR as f32) {
        s.record(format!("voice_band_{band}"), level);
    }

    let (tout, _) = render_set(&voice, &[(dbl::P_MODE, 1.0), (dbl::P_VOICES, 4.0)]);
    s.record("tuned4_voice_gain_db", probes::gain_db(&voice, &tout));
    s.record("tuned4_voice_max_step", probes::max_step(&tout));

    let noise = probes::noise(frames, 0.3);
    let (nout, _) = render_effect::<Target>(SR, &noise, &noise);
    s.record("noise_gain_db", probes::gain_db(&noise, &nout));
    s.record("noise_max_step", probes::max_step(&nout));

    let imp = probes::impulse(frames);
    let (iout, _) = render_effect::<Target>(SR, &imp, &imp);
    s.record("impulse_rms_db", db(probes::rms(&iout)));
    s.record("impulse_peak_db", db(probes::peak(&iout)));

    sdsp_test_kit::params::record_table(&mut s, dbl::PARAMS);
    s.finish();
}

#[test]
fn clap_mix_zero_is_the_dry_signal_delayed_by_the_reported_latency() {
    let x = sdsp_test_kit::signals::voiced(1.0);
    let (out, _) = render_set(&x, &[(dbl::P_MIX, 0.0)]);
    let lat = superduper_synth_core::doubler::Doubler::new(SR as f32, 512).latency_samples() as usize;
    // Past the 5 ms Mix glide from the default, the output IS the input.
    // The kit renders whole 512-frame blocks only; the tail stays zero.
    for i in 4800..out.len() / 512 * 512 {
        assert_eq!(out[i].to_bits(), x[i - lat].to_bits(), "sample {i}");
    }
}

#[test]
fn parameter_table_is_consistent() {
    sdsp_test_kit::params::check_table("superduper-double", dbl::PARAMS, dbl::STEPPED_PARAMS);
}

#[global_allocator]
static ALLOC: sdsp_test_kit::alloc::CountingAllocator = sdsp_test_kit::alloc::CountingAllocator;

#[test]
fn process_does_not_allocate() {
    // Every mode, all four voices, the bus key on, and a mode switch into
    // Tuned Lead mid-stream (the lead engine resets on the audio thread).
    let frames = 1 << 15;
    let noise = probes::noise(frames, 0.3);
    sdsp_test_kit::alloc::reset();
    let _ = render_effect::<Target>(SR, &noise, &noise);
    let mode = ClapId::new(dbl::P_MODE as u32);
    let _ = sdsp_test_kit::host::render_with::<Target>(SR, 512, &noise, &noise, move |pos, buf| {
        let ev = |id: usize, v: f64| ParamValueEvent::new(0, ClapId::new(id as u32), Pckn::match_all(), v, Cookie::empty());
        match pos {
            0 => {
                buf.push(&ev(dbl::P_VOICES, 4.0));
                buf.push(&ev(dbl::P_KEY_OPEN, 1.0));
                buf.push(&ParamValueEvent::new(0, mode, Pckn::match_all(), 1.0, Cookie::empty()));
            }
            8192 => buf.push(&ParamValueEvent::new(0, mode, Pckn::match_all(), 2.0, Cookie::empty())),
            20480 => buf.push(&ev(dbl::P_VOICES, 1.0)),
            _ => {}
        }
    });
    sdsp_test_kit::alloc::assert_rt_clean("superduper-double", 2 * frames / 512);
}
